<div class="row g-3"><div class="col-lg-7"><div class="card-panel mb-3"><div class="panel-head"><div><h3>Profile</h3><p>Personal settings stored on your ServicePro account.</p></div></div><form class="ajax-form" method="post" enctype="multipart/form-data" action="<?= url('/profile') ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" value="<?= e($profile['name']) ?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" value="<?= e($profile['email']) ?>" disabled></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?= e($profile['phone']??'') ?>"></div><div class="col-md-6"><label class="form-label">Photo</label><input class="form-control" type="file" accept="image/jpeg,image/png" name="photo"></div><div class="col-md-6"><label class="form-label">Language</label><select class="form-select" name="language"><option value="id" <?= $profile['language']==='id'?'selected':'' ?>>Bahasa Indonesia</option><option value="en" <?= $profile['language']==='en'?'selected':'' ?>>English</option></select></div><div class="col-md-6"><label class="form-label">Theme</label><select class="form-select" name="theme"><option value="system" <?= $profile['theme']==='system'?'selected':'' ?>>System</option><option value="light" <?= $profile['theme']==='light'?'selected':'' ?>>Light</option><option value="dark" <?= $profile['theme']==='dark'?'selected':'' ?>>Dark</option></select></div><div class="col-12"><button class="btn btn-primary">Save Profile</button></div></div></form></div><div class="card-panel"><h3 class="h6">Change Password</h3><form class="ajax-form" method="post" action="<?= url('/profile/password') ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-4"><label class="form-label">Current</label><input class="form-control" type="password" name="current_password" required></div><div class="col-md-4"><label class="form-label">New Password</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="col-md-4"><label class="form-label">Confirm</label><input class="form-control" type="password" name="password_confirmation" minlength="8" required></div><div class="col-12"><button class="btn btn-outline-primary">Change Password</button></div></div></form></div></div><div class="col-lg-5"><div class="card-panel"><div class="panel-head"><div><h3>Active Sessions</h3><p>Devices currently signed into your account.</p></div><button class="btn btn-sm btn-outline-danger ajax-action" data-url="<?= url('/profile/sessions/revoke-all') ?>">Logout other devices</button></div><?php foreach($sessions as $s):?><div class="notification-item"><i class="bi bi-display fs-5"></i><div class="flex-grow-1"><strong><?= $s['session_hash']===$currentSession?'This device':'Active device' ?></strong><small class="d-block text-secondary"><?= e($s['ip_address']??'-') ?> · <?= e(mb_strimwidth($s['user_agent']??'',0,62,'…')) ?></small><small class="text-secondary">Last seen <?= e($s['last_seen_at']) ?></small></div><button class="btn btn-sm btn-light text-danger ajax-action" data-url="<?= url('/profile/sessions/'.$s['id'].'/revoke') ?>"><i class="bi bi-box-arrow-right"></i></button></div><?php endforeach;?><?php if(!$sessions):?><div class="empty-state">No tracked active sessions yet.</div><?php endif;?></div></div></div>
